package com.tradereview.app.v200

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.verticalScroll
import androidx.compose.foundation.rememberScrollState
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.runtime.saveable.rememberSaveable
import androidx.compose.runtime.saveable.listSaver
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.testTag
import androidx.compose.ui.unit.dp
import com.tradereview.app.data.newKey
import java.time.LocalDate

@Composable fun V200Reviews(model:V200ViewModel,state:LedgerSnapshot){var tab by rememberSaveable{mutableStateOf("plan")};var showPlan by rememberSaveable{mutableStateOf(false)};var planId by rememberSaveable{mutableStateOf<String?>(null)};var selectedCycle by rememberSaveable{mutableStateOf<String?>(null)};var reviewId by rememberSaveable{mutableStateOf<String?>(null)};var showReview by rememberSaveable{mutableStateOf(false)}
    LazyColumn(Modifier.fillMaxSize().testTag("v2-reviews"),contentPadding=PaddingValues(12.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
        item{ChoiceRow(tab,listOf("plan" to "盘前计划","post" to "盘后复盘"),{tab=it},"review-section-")}
        if(tab=="plan"){item{Button({planId=null;showPlan=true},modifier=Modifier.fillMaxWidth().heightIn(min=52.dp).testTag("new-plan")){Text("新增具体标的计划")}};if(state.plans.isEmpty())item{EmptyLedger("可为尚未持仓的股票或合约制定计划，同一天可有多个计划。")};items(state.plans.sortedByDescending{it.day},key={it.id}){p->LedgerPanel("${p.name} ${p.code}"){Text("${LocalDate.ofEpochDay(p.day)} · ${state.accounts.first{it.id==p.accountId}.name}");Text("策略 ${strategyLabel(state,p.strategyId)}");if(p.note.isNotEmpty())Text(p.note.take(100));TextButton({planId=p.id;showPlan=true},modifier=Modifier.heightIn(min=48.dp)){Text("查看与编辑计划")}}}}
        else{if(state.cycles.isEmpty())item{EmptyLedger("尚无真实建立的持仓，不能凭空复盘。")};items(state.cycles.sortedByDescending{it.firstDay},key={it.id}){c->LedgerPanel("${c.name} ${c.code} · ${if(c.closedDay==null)"持有中"else"已平仓"}"){Text("${state.accounts.first{it.id==c.accountId}.name} · ${directionLabel(c)}");Text("${LocalDate.ofEpochDay(c.firstDay)} · 已实现 ${amount(c.realized)}");TextButton({selectedCycle=c.id;reviewId=null;showReview=true},modifier=Modifier.heightIn(min=48.dp).testTag("review-cycle-${c.id}")){Text("新增本次复盘")};state.reviews.filter{it.cycleId==c.id}.sortedByDescending{it.day}.forEach{r->TextButton({selectedCycle=c.id;reviewId=r.id;showReview=true},modifier=Modifier.heightIn(min=48.dp)){Text("${LocalDate.ofEpochDay(r.day)} ${r.note.take(24).ifBlank{"已有复盘"}}")}}}}}
    }
    if(showPlan)PlanDialog(model,state,state.plans.firstOrNull{it.id==planId},{showPlan=false})
    if(showReview)state.cycles.firstOrNull{it.id==selectedCycle}?.let{c->ReviewDialog(model,state,c,state.reviews.firstOrNull{it.id==reviewId},{showReview=false})}
}
private val KeyTextSaver=listSaver<List<String>,String>(save={it},restore={it.toList()})
@Composable private fun KeyPrices(labels:List<String>,prices:List<String>,onChange:(List<String>,List<String>)->Unit){Text("关键价位（空价格不保存）",style=MaterialTheme.typography.labelLarge);labels.indices.forEach{i->Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){EntryField("名称",labels[i],{v->onChange(labels.toMutableList().apply{set(i,v)},prices)},modifier=Modifier.weight(1f));EntryField("价位",prices[i],{v->onChange(labels,prices.toMutableList().apply{set(i,v)})},number=true,modifier=Modifier.weight(1f));TextButton({onChange(labels.filterIndexed{n,_->n!=i},prices.filterIndexed{n,_->n!=i})},modifier=Modifier.heightIn(min=48.dp)){Text("删")}}};if(labels.size<30)TextButton({onChange(labels+"",prices+"")},modifier=Modifier.heightIn(min=48.dp)){Text("增加关键价位")}}
private fun levelText(labels:List<String>,prices:List<String>)=LedgerJson.text(labels.indices.filter{prices[it].isNotBlank()}.map{KeyPrice(labels[it].trim(),prices[it].trim())})
@Composable private fun PlanDialog(model:V200ViewModel,state:LedgerSnapshot,value:LedgerPlan?,onDismiss:()->Unit){var account by rememberSaveable(value?.id){mutableStateOf(value?.accountId?:"stock")};var code by rememberSaveable(value?.id){mutableStateOf(value?.code.orEmpty())};var name by rememberSaveable(value?.id){mutableStateOf(value?.name.orEmpty())};var day by rememberSaveable(value?.id){mutableLongStateOf(value?.day?:AutomaticEntry.today().toEpochDay())};var strategy by rememberSaveable(value?.id){mutableStateOf(value?.strategyId)};var entry by rememberSaveable(value?.id){mutableStateOf(value?.entryPrice.orEmpty())};var tp by rememberSaveable(value?.id){mutableStateOf(value?.takeProfit.orEmpty())};var stop by rememberSaveable(value?.id){mutableStateOf(value?.stopLoss.orEmpty())};var note by rememberSaveable(value?.id){mutableStateOf(value?.note.orEmpty())};val original=remember(value?.id){value?.let{LedgerJson.levels(it.levels)}?:listOf(KeyPrice("支撑",""),KeyPrice("压力",""))};var labels by rememberSaveable(value?.id,stateSaver=KeyTextSaver){mutableStateOf(original.map{it.label})};var prices by rememberSaveable(value?.id,stateSaver=KeyTextSaver){mutableStateOf(original.map{it.price})};var error by remember{mutableStateOf<String?>(null)}
    AlertDialog(onDismissRequest=onDismiss,title={Text("具体标的盘前计划")},text={Column(Modifier.heightIn(max=430.dp).verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(8.dp)){
        error?.let{Text(it,color=MaterialTheme.colorScheme.error)};ChoiceRow(account,listOf("stock" to "A股账户","futures" to "期货账户"),{account=it});DateControl(day,{day=it},"计划日期");EntryField("股票/合约代码",code,{code=it.lowercase()},"plan-code");EntryField("名称",name,{name=it},"plan-name");StrategySelect(state,strategy,{strategy=it});EntryField("计划入场价（可选）",entry,{entry=it},"plan-entry",true);EntryField("计划止盈价（可选）",tp,{tp=it},number=true);EntryField("计划止损价（可选）",stop,{stop=it},number=true);KeyPrices(labels,prices,{l,p->labels=l.toList();prices=p.toList()});EntryField("自由文字计划",note,{note=it},"plan-note",lines=3)
    }},confirmButton={TextButton({val p=LedgerPlan(value?.id?:newKey(),account,code.trim().lowercase(),name.trim(),day,strategy,entry.trim().ifBlank{null},tp.trim().ifBlank{null},stop.trim().ifBlank{null},levelText(labels,prices),note);try{LedgerValidation.plan(p);model.plan(p);onDismiss()}catch(e:IllegalArgumentException){error=e.message}},modifier=Modifier.heightIn(min=48.dp).testTag("save-plan")){Text("保存计划")}},dismissButton={TextButton(onDismiss){Text("取消")}})
}
@Composable private fun ReviewDialog(model:V200ViewModel,state:LedgerSnapshot,cycle:LedgerCycle,value:LedgerReview?,onDismiss:()->Unit){var day by rememberSaveable(value?.id,cycle.id){mutableLongStateOf(value?.day?:AutomaticEntry.today().toEpochDay())};var tp by rememberSaveable(value?.id,cycle.id){mutableStateOf(value?.takeProfit.orEmpty())};var stop by rememberSaveable(value?.id,cycle.id){mutableStateOf(value?.stopLoss.orEmpty())};var note by rememberSaveable(value?.id,cycle.id){mutableStateOf(value?.note.orEmpty())};val original=remember(value?.id){value?.let{LedgerJson.levels(it.levels)}?:emptyList()};var labels by rememberSaveable(value?.id,cycle.id,stateSaver=KeyTextSaver){mutableStateOf(original.map{it.label})};var prices by rememberSaveable(value?.id,cycle.id,stateSaver=KeyTextSaver){mutableStateOf(original.map{it.price})};var error by remember{mutableStateOf<String?>(null)}
    val executionIds=state.lots.filter{it.cycleId==cycle.id}.map{it.executionId}.toSet()+state.matches.filter{it.cycleId==cycle.id}.map{it.closeExecutionId};val facts=MatchingEngine.ordered(state.executions.filter{it.id in executionIds})
    AlertDialog(onDismissRequest=onDismiss,title={Text("${cycle.name} ${cycle.code} 复盘")},text={Column(Modifier.heightIn(max=450.dp).verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(8.dp)){
        error?.let{Text(it,color=MaterialTheme.colorScheme.error)};Text("${state.accounts.first{it.id==cycle.accountId}.name} · ${directionLabel(cycle)}");Text("开仓/买入 ${LocalDate.ofEpochDay(cycle.firstDay)}\n平仓/卖出 ${cycle.closedDay?.let{LocalDate.ofEpochDay(it)}?:"仍持有"}");Text("平均开仓价 ${amount(cycle.averagePrice)} · 剩余 ${cycle.remaining}\n实际费用 ${amount(cycle.fees)}");NetText(cycle.realized?.let(::decimal));if(cycle.accountId=="futures")Text("参考保证金 ${amount(cycle.referenceMargin)}");Text("当前止盈 ${cycle.takeProfit?.let(::amount)?:"未设置"} · 止损 ${cycle.stopLoss?.let(::amount)?:"未设置"}");facts.forEach{e->Text("${LocalDate.ofEpochDay(e.date)} ${actionLabel(e)} · ${e.quantity} × ${amount(e.price)} · 费用${amount(e.fees)}",style=MaterialTheme.typography.bodySmall)}
        HorizontalDivider();DateControl(day,{day=it},"复盘日期");EntryField("复盘记录的止盈价（可选）",tp,{tp=it},number=true);EntryField("复盘记录的止损价（可选）",stop,{stop=it},number=true);KeyPrices(labels,prices,{l,p->labels=l.toList();prices=p.toList()});EntryField("自由文字复盘",note,{note=it},"position-review-note",lines=3)
    }},confirmButton={TextButton({val r=LedgerReview(value?.id?:newKey(),cycle.id,day,tp.trim().ifBlank{null},stop.trim().ifBlank{null},levelText(labels,prices),note);try{LedgerValidation.review(r);model.review(r);onDismiss()}catch(e:IllegalArgumentException){error=e.message}},modifier=Modifier.heightIn(min=48.dp).testTag("save-position-review")){Text("保存复盘")}},dismissButton={TextButton(onDismiss){Text("取消")}})
}
